using System;using System.Data;using System.Data.SqlClient;using System.Diagnostics;using System.IO;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class DocumentCenterPage:UserControl{ComboBox candidate,type;TextBox title,path;DataGridView grid;public DocumentCenterPage(){if(!AppSession.Can("Candidates.View")){Controls.Add(Ui.Label(L.Fa?"دسترسی ندارید":"Access denied",16,true));return;}Dock=DockStyle.Fill;Padding=new Padding(8);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=90,AutoScroll=true};candidate=new ComboBox{Width=220,DropDownStyle=ComboBoxStyle.DropDownList};type=new ComboBox{Width=140,DropDownStyle=ComboBoxStyle.DropDownList};type.Items.AddRange(new object[]{"Resume","Certificate","Portfolio","Identity","Other"});type.SelectedIndex=0;title=Ui.Text();title.Width=180;path=Ui.Text();path.Width=280;var browse=Ui.Button(L.Fa?"انتخاب فایل":"Browse",false);browse.Click+=(s,e)=>Browse();var add=Ui.Button(L.Fa?"افزودن سند":"Add document");add.Click+=(s,e)=>Add();var open=Ui.Button(L.Fa?"باز کردن":"Open",false);open.Click+=(s,e)=>Open();bar.Controls.AddRange(new Control[]{Ui.Label(L.Fa?"کارجو":"Candidate"),candidate,Ui.Label(L.Fa?"نوع":"Type"),type,title,path,browse,add,open});grid=Ui.Grid();Controls.Add(grid);Controls.Add(bar);LoadCandidates();LoadRows();}void LoadCandidates(){var t=Database.Query("SELECT Id,FullName FROM Candidates ORDER BY FullName");candidate.DataSource=t;candidate.DisplayMember="FullName";candidate.ValueMember="Id";}void Browse(){using(var d=new OpenFileDialog{Filter="Documents|*.pdf;*.doc;*.docx;*.jpg;*.jpeg;*.png|All files|*.*"})if(d.ShowDialog()==DialogResult.OK){path.Text=d.FileName;if(string.IsNullOrWhiteSpace(title.Text))title.Text=Path.GetFileName(d.FileName);}}void Add(){if(candidate.SelectedValue==null||string.IsNullOrWhiteSpace(path.Text))return;Database.Exec("INSERT CandidateDocuments(CandidateId,Title,FilePath,DocumentType) VALUES(@c,@t,@p,@d)",new SqlParameter("@c",candidate.SelectedValue),new SqlParameter("@t",title.Text),new SqlParameter("@p",path.Text),new SqlParameter("@d",type.Text));Database.Audit("Create","CandidateDocument",title.Text);LoadRows();}void Open(){if(grid.CurrentRow==null)return;var p=Convert.ToString(grid.CurrentRow.Cells["FilePath"].Value);if(File.Exists(p))Process.Start(p);else MessageBox.Show(L.Fa?"فایل پیدا نشد":"File not found");}void LoadRows(){grid.DataSource=Database.Query("SELECT d.Id,c.FullName Candidate,d.Title,d.DocumentType,d.FilePath,d.CreatedAt FROM CandidateDocuments d JOIN Candidates c ON c.Id=d.CandidateId ORDER BY d.Id DESC");}}}
